if __name__ == "__main__":
    load_fonts()
    # Nadie con tu usuario puede leer la memoria de la ventana (donde pasa la contraseña) ni
    # engancharse a ella (PR_SET_DUMPABLE = 0)
    try:
        import ctypes
        ctypes.CDLL(None).prctl(4, 0, 0, 0, 0)
    except (OSError, AttributeError):
        pass
    # Mismo identificador que StartupWMClass del acceso: asi el dock agrupa la ventana con su icono
    GLib.set_prgname(APP_ID)
    Gdk.set_program_class(APP_ID)
    # Las ventanas de versiones anteriores que sigan en marcha se cierran: hasta la 1.56.14 podian quedarse
    # dando vueltas sin ventana, y la siguiente vez que se abria, el sistema le pasaba la peticion a una de
    # ellas (con el codigo de antes) en lugar de abrir esta
    close_stale_windows(sys.argv[1] if len(sys.argv) > 1 else "")
    # La ventana es App2 (desde la 1.54): App lleva toda la logica (datos, tareas y dialogos) y App2 la
    # organizacion y el aspecto. Al acabar, se sale del todo (sin esperar a ningun hilo)
    rc = App2().run([sys.argv[0]])
    sys.stdout.flush()
    os._exit(rc or 0)
LVM_GUI_PY
}

# ===========================================================================
# Linea de comandos
# ===========================================================================

function cli_install() {
    local xampp="" php="" yes=0 selected="" b full branch

    while [ -n "$1" ]; do
        case "$1" in
            --xampp) xampp=${2//,/ }; shift 2 ;;
            --php) php=${2//,/ }; shift 2 ;;
            --base) echo "Aviso: --base ya no se usa (las versiones de PHP tienen su pila propia)"; shift 2 ;;
            --si|--yes|-y) yes=1; shift ;;
            *) echo "Opcion desconocida: $1"; return 1 ;;
        esac
    done

    for b in $xampp; do
        catalog_entry "$b" > /dev/null || { echo "XAMPP $b no esta en el catalogo"; return 1; }
        [ -e "/opt/lampp-$b" ] && echo "lampp-$b ya existe, se omite" && continue
        selected+=" xampp:$b"
    done

    if [ -n "$php" ]; then
        local releases=$(php_releases)

        # 8.4 = ultimo parche de la rama; 8.4.10 = ese parche concreto
        local item latest
        for branch in $php; do
            if [[ "$branch" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
                full=$branch
                latest=$(awk -v b="${full%.*}" '$1 == b {print $2}' <<< "$releases")
                if [ -z "$latest" ] || ! php_patches "${full%.*}" | awk -v v="$full" '$1 == v {f = 1} END {exit !f}'; then
                    echo "PHP $full no esta publicada en php.net o su rama no se ofrece, se omite"
                    continue
                fi
                item=$(php_item "$full" "$latest")
            else
                full=$(awk -v b="$branch" '$1 == b {print $2}' <<< "$releases")
                [ -z "$full" ] && echo "PHP $branch no esta disponible en php.net, se omite" && continue
                item=$(php_item "$full" "$full")
            fi
            [ -e "${TEST_DIR:-/opt}/lampp-$(item_folder "$item")" ] && echo "lampp-$(item_folder "$item") ya existe, se omite" && continue
            local have=$(php_installed_in "$full")
            [ -n "$have" ] && echo "PHP $full ya esta instalada en $have, se omite" && continue
            selected+=" $item"
        done
    fi

    [ -z "$selected" ] && echo "No hay nada que instalar." && return 0

    echo "Se va a instalar:$selected"

    if [ $yes -ne 1 ]; then
        read -p "¿Continuar? [s/N]: " answer
        [[ "$answer" =~ ^[sSyY]$ ]] || return 0
    fi

    UI=text
    install_plan "$selected"
}

# rehacer|actualizar <version> [--copia]: con --copia, si su MariaDB cambia de rama (empieza con BBDD
# vacias), antes se guardan las de ahora en ~/nexum-backups
function cli_rebuild() {
    local version=$1
    [ "$2" == "--copia" ] && STACK_DB_COPY=1
    local dir=${TEST_DIR:-/opt}/lampp-$version

    if [ -z "$version" ] || ! is_fpm_install "$dir"; then
        echo "lampp-$version no existe o no es una version de PHP nueva (los XAMPP no se rehacen)"

        return 1
    fi

    # Una version con un parche concreto (lampp-8.3.10) se queda en ese parche
    local php=$(stack_fields "$dir" | cut -d'|' -f1)
    if [ "$version" != "${php%.*}" ]; then
        echo "lampp-$version tiene un parche concreto de PHP y no se actualiza. Si necesitas otro, instalalo aparte."

        return 1
    fi

    local full=$(rebuild_version "$dir" "$(php_releases)")
    if [ -z "$full" ]; then
        echo "No se encuentra en php.net la ultima version de la rama de lampp-$version"

        return 1
    fi

    if is_stack_install "$dir" && [ "$(stack_fields "$dir")" == "$(stack_versions "$full")" ] \
            && { ! php2shell_backport "$full" > /dev/null || [ -f "$dir/$PHP2SHELL_MARK" ]; }; then
        if [ -t 1 ]; then
            echo -e "\033[1;32mEl paquete lampp-$version se encuentra actualizado.\033[0m No hay nada que actualizar."
        else
            echo "El paquete lampp-$version se encuentra actualizado. No hay nada que actualizar."
        fi

        return 0
    fi

    UI=text
    install_plan "rehacer:$full"
}

# ===========================================================================
# Componentes: los parches nuevos de todo lo que usa el gestor
# ===========================================================================
# Lo que tiene un parche nuevo publicado: cada version de PHP (su PHP, Apache, MariaDB, ProFTPD, Perl y
# phpMyAdmin, frente a lo ultimo de su rama), las imagenes de Docker que se usan (las MariaDB comunes,
# phpMyAdmin y la base de cada imagen de PHP, frente a su huella en Docker Hub: sin descargar nada), y
# Mailpit y cloudflared (frente a los que pone esta version del gestor). componentes [--sin-docker]:
#   L|carpeta|componente|instalada|nueva   una version de PHP: se rehace entera con lo ultimo de su rama
#   F|carpeta|motivo                       una version que no se pone al dia sola (parche concreto, XAMPP)
#   K|imagen|para que                      una imagen de Docker con una version nueva en Docker Hub
#   X|programa|instalada|nueva             Mailpit o cloudflared
#   E|lo que no se ha podido consultar
#   S|cuantos componentes tienen parche nuevo
function components_check() {
    local dir name full cur new i n=0 names=(PHP Apache MariaDB ProFTPD Perl phpMyAdmin) releases img v
    local a b
    releases=$(php_releases)
    [ -z "$releases" ] && echo "E|php.net (las versiones de PHP)"
    for dir in $(lampp_dirs); do
        name=${dir#/opt/lampp-}
        is_fpm_install "$dir" || { echo "F|$name|XAMPP oficial: no se rehace (instala una versión de PHP nueva al lado)"; continue; }
        cur=$(stack_fields "$dir")
        [ "$name" != "$(cut -d'|' -f1 <<< "$cur" | sed 's/\.[0-9]*$//')" ] && { echo "F|$name|parche concreto de PHP: se queda en el suyo"; continue; }
        [ -z "$releases" ] && continue
        full=$(rebuild_version "$dir" "$releases")
        [ -z "$full" ] && { echo "E|la última versión de la rama de lampp-$name"; continue; }
        new=$(stack_versions "$full")
        IFS='|' read -r -a a <<< "$cur"
        IFS='|' read -r -a b <<< "$new"
        for i in 0 1 2 3 4 5; do
            # (lo que no se ha podido consultar sale como su rama seguida de .x: no cuenta)
            [ -z "${b[$i]}" ] || [[ "${b[$i]}" == *.x ]] && continue
            if [ "${a[$i]}" != "${b[$i]}" ] && [ "$(printf '%s\n%s\n' "${a[$i]}" "${b[$i]}" | sort -V | tail -1)" == "${b[$i]}" ]; then
                echo "L|$name|${names[$i]}|${a[$i]:-?}|${b[$i]}"
                n=$((n + 1))
            fi
        done
    done
    if [ "$1" != --sin-docker ] && docker_ready > /dev/null 2>&1; then
        for v in $(docker_maria_versions); do
            img=mariadb:$v
            docker_image_outdated "$img" && { echo "K|$img|la MariaDB $v común de Docker"; n=$((n + 1)); }
        done
        if dk image inspect "$DOCKER_PMA_IMAGE" > /dev/null 2>&1 && docker_image_outdated "$DOCKER_PMA_IMAGE"; then
            echo "K|$DOCKER_PMA_IMAGE|phpMyAdmin de Docker"
            n=$((n + 1))
        fi
        for v in $DOCKER_PHP_VERSIONS; do
            dk image inspect "nexum-php:$v" > /dev/null 2>&1 || continue
            img=php:$v-fpm
            docker_image_outdated "$img" && { echo "K|$img|la imagen de PHP $v de Docker (nexum-php:$v)"; n=$((n + 1)); }
        done
    fi
    if mailpit_installed && [ "$(mailpit_installed_version)" != "$MAILPIT_VERSION" ]; then
        echo "X|Mailpit|$(mailpit_installed_version)|$MAILPIT_VERSION"
        n=$((n + 1))
    fi
    if tunnel_installed && [ "$(tunnel_installed_version)" != "$TUNNEL_VERSION" ]; then
        echo "X|cloudflared|$(tunnel_installed_version)|$TUNNEL_VERSION"
        n=$((n + 1))
    fi
    echo "S|$n"
}

# ¿Hay en Docker Hub una version nueva de una imagen que ya esta en este equipo? Compara su huella
# (la de la etiqueta, con una consulta HEAD que no cuenta para los limites de Docker Hub) con la de
# la descargada. Sin la imagen o sin respuesta: no (no se puede saber)
function docker_image_outdated() {
    local img=$1 repo tag token remote local_d
    repo=${img%%:*} tag=${img#*:}
    [[ "$repo" == */* ]] || repo=library/$repo
    local_d=$(dk image inspect --format '{{range .RepoDigests}}{{println .}}{{end}}' "$img" 2> /dev/null | sed -n 's/^[^@]*@//p' | head -1)
    [ -z "$local_d" ] && return 1
    token=$(curl -q --proto =https -fsS --max-time 15 "https://auth.docker.io/token?service=registry.docker.io&scope=repository:$repo:pull" 2> /dev/null \
        | python3 -I -c 'import json, sys; print(json.load(sys.stdin)["token"])' 2> /dev/null) || return 1
    remote=$(curl -q --proto =https -fsSI --max-time 15 -H "Authorization: Bearer $token" \
        -H "Accept: application/vnd.oci.image.index.v1+json, application/vnd.docker.distribution.manifest.list.v2+json, application/vnd.docker.distribution.manifest.v2+json, application/vnd.oci.image.manifest.v1+json" \
        "https://registry-1.docker.io/v2/$repo/manifests/$tag" 2> /dev/null | tr -d '\r' | sed -n 's/^[Dd]ocker-[Cc]ontent-[Dd]igest: *//p' | head -1)
    [[ "$remote" =~ ^sha256:[0-9a-f]{64}$ ]] || return 1
    [ "$remote" != "$local_d" ]
}

# componentes-actualizar: pone al dia todo lo que diga components_check. Las versiones de PHP se rehacen
# (la de ahora sigue funcionando mientras se compila); las MariaDB comunes, phpMyAdmin y las imagenes de
# PHP se descargan de nuevo y sus contenedores en marcha se rehacen (unos segundos sin servicio: su BBDD
# y su configuracion no cambian); Mailpit y cloudflared se instalan con su version. --copia: a cada
# version que se rehace (como actualizar --copia)
function components_update() {
    local out line f cf folders="" imgs="" progs="" fail=0 v slug dir running
    [ "$1" == "--copia" ] && STACK_DB_COPY=1
    echo "Buscando parches nuevos..."
    out=$(components_check)
    while IFS= read -r line; do
        IFS='|' read -r -a f <<< "$line"
        case ${f[0]} in
            L) echo "  lampp-${f[1]}: ${f[2]} ${f[3]} → ${f[4]}"
               [[ " $folders " == *" ${f[1]} "* ]] || folders+=" ${f[1]}" ;;
            K) echo "  ${f[1]} (${f[2]}): versión nueva en Docker Hub"; imgs+=" ${f[1]}" ;;
            X) echo "  ${f[1]}: ${f[2]} → ${f[3]}"; progs+=" ${f[1]}" ;;
            E) echo "  (no se ha podido consultar: ${f[1]})" ;;
        esac
    done <<< "$out"
    if [ -z "$folders$imgs$progs" ]; then
        echo "Todo está al día: no hay parches nuevos."
        return 0
    fi
    [ "$DRY" -eq 1 ] && { echo "  [simulacion] se actualizaria lo de arriba"; return 0; }
    local steps=()
    for v in $imgs; do
        case $v in
            mariadb:*) steps+=("MariaDB ${v#mariadb:} de Docker") ;;
            "$DOCKER_PMA_IMAGE") steps+=("phpMyAdmin de Docker") ;;
            php:*) v=${v#php:}; steps+=("Imagen de PHP ${v%-*}") ;;
            *) steps+=("$v") ;;
        esac
    done
    for v in $progs; do steps+=("$v"); done
    for v in $folders; do steps+=("lampp-$v"); done
    task_plan "Actualizando los componentes" "${steps[@]}"
    for v in $imgs; do
        task_step
        case $v in
            mariadb:*)
                v=${v#mariadb:}
                echo "MariaDB $v común de Docker: la imagen nueva y su contenedor de nuevo (sus BBDD no cambian)"
                # (y, de paso, que se ponga al dia sola al cambiar de parche: MARIADB_AUTO_UPGRADE)
                cf=$DOCKER_DIR/mariadb-$v/compose.yaml
                if dk pull "mariadb:$v" && awk '/^      MARIADB_AUTO_UPGRADE:/ { next } { print } /^      MARIADB_ROOT_PASSWORD: / { print "      MARIADB_AUTO_UPGRADE: \"1\"" }' "$cf" > "$cf.nuevo" \
                        && chmod 600 "$cf.nuevo" && mv -f "$cf.nuevo" "$cf"; then
                    [ -n "$(dk ps -q --filter "name=^$(docker_maria_name "$v")\$" 2> /dev/null)" ] && { docker_maria_up "$v" > /dev/null || fail=1; }
                else
                    fail=1
                fi ;;
            "$DOCKER_PMA_IMAGE")
                echo "phpMyAdmin de Docker: la imagen nueva"
                dk pull "$DOCKER_PMA_IMAGE" || { fail=1; continue; }
                [ "$(docker_web_state)" == marcha ] && { docker_web_up > /dev/null || fail=1; } ;;
            php:*)
                v=${v#php:}; v=${v%-fpm}
                echo "Imagen de PHP $v de Docker: de nuevo, con lo último de Docker Hub"
                docker_php_image "$v" --nueva || { echo "No se ha podido rehacer la imagen de PHP $v: sigue con la anterior"; fail=1; continue; }
                for slug in $(docker_projects); do
                    [[ " $(docker_conf "$slug" PHP) " == *" $v "* ]] || continue
                    dir=$DOCKER_DIR/$slug
                    running=$(dk ps --filter "label=com.docker.compose.project=nexum-$slug" --format '{{.Label "com.docker.compose.service"}}' 2> /dev/null)
                    [ -n "$running" ] && { dk compose --project-directory "$dir" -f "$dir/compose.yaml" up -d $running > /dev/null || fail=1; }
                done ;;
        esac
    done
    [ -n "$imgs" ] && dk image prune -f > /dev/null 2>&1
    [[ " $progs " == *" Mailpit "* ]] && { task_step; mailpit_install || fail=1; }
    [[ " $progs " == *" cloudflared "* ]] && { task_step; tunnel_install || fail=1; }
    for v in $folders; do
        task_step
        echo "lampp-$v: se rehace con lo último de su rama (sigue funcionando mientras se compila)"
        ( cli_rebuild "$v" ) || fail=1
    done
    [ $fail -eq 0 ] && echo "Todo al día." || echo "Algo no se ha podido actualizar: mira lo de arriba."
    return $fail
}

# actualizar-a <version> <php>: pasa una version a otro parche de PHP de su rama. Para las que no se
# actualizan en su carpeta: una lampp-X.Y.Z (se queda en su parche) o un XAMPP (sus binarios no se
# pueden arreglar). Instala PHP <php> con su pila propia en lampp-<php>, al lado (la de antes no se
# toca), le copia todas las BBDD de la de antes con sus vinculos a las carpetas de los proyectos
# (como copiar-bd: la de antes sigue igual) y, si la de antes era la activa, activa la nueva. La de
# antes se queda hasta que la desinstales. Si <php> es el mismo parche de una pila propia sin el
# parche de seguridad (7.4.33, 8.0.30, 8.1.34), se vuelve a compilar en su carpeta con el
function upgrade_to() {
    local from=$1 php=$2 to=$2 src dst old db link failed=() n=0 owner have
    # (--copia: para cuando se vuelve a compilar en su carpeta, como actualizar --copia)
    [ "$3" == "--copia" ] && STACK_DB_COPY=1
    if [ -z "$from" ] || ! [[ "$php" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; then
        echo "Uso: nexum actualizar-a <version instalada> <version de PHP, como 8.3.36>"
        return 1
    fi
    valid_version_name "$from" || { echo "Version no valida"; return 1; }
    src=${TEST_DIR:-/opt}/lampp-$from dst=${TEST_DIR:-/opt}/lampp-$php
    [ -d "$src" ] && [ ! -L "$src" ] || { echo "No existe la version lampp-$from"; return 1; }
    old=$(stack_fields "$src" | cut -d'|' -f1)
    if [ "${old%.*}" != "${php%.*}" ]; then
        echo "lampp-$from es PHP $old: solo se pasa a otro parche de su rama (${old%.*}.x)"
        return 1
    fi
    if [ "$(printf '%s\n' "$old" "$php" | sort -V | tail -1)" != "$php" ]; then
        echo "PHP $php es anterior a PHP $old: no se actualiza hacia atras"
        return 1
    fi
    if [ "$src" == "$dst" ]; then
        if ! is_stack_install "$src" || ! php2shell_backport "$php" > /dev/null || [ -f "$src/$PHP2SHELL_MARK" ]; then
            echo "lampp-$from ya es PHP $php: no hay nada que actualizar"
            return 0
        fi
        echo "lampp-$from se vuelve a compilar con el parche de seguridad de PHP2Shell (conserva sus BBDD"
        echo "si su MariaDB sigue en la misma rama; si no, empieza con BBDD vacias$([ "${STACK_DB_COPY:-0}" -eq 1 ] && echo ", con una copia antes en ~/nexum-backups"))"
        UI=text
        install_plan "reparar:$php"
        return
    fi
    # (si PHP <php> ya esta en otra carpeta, como lampp-8.2 con la 8.2.35, las BBDD van ahi)
    have=$(php_installed_in "$php")
    if [ -n "$have" ] && [ "$have" != "$src" ] && [ -z "$TEST_DIR" ]; then
        dst=$have to=${have#/opt/lampp-}
    fi
    if [ -e "$dst" ]; then
        if ! is_fpm_install "$dst" || [ "$(php_version "$dst")" != "$php" ]; then
            echo "Ya existe $dst y no es PHP $php: no se cambia nada"
            return 1
        fi
        echo "lampp-$to ya esta instalada: solo se le copian las BBDD de lampp-$from"
    else
        echo "Se instala PHP $php en lampp-$to, al lado de lampp-$from (que no se toca)"
        UI=text
        install_plan "php:$php" || return 1
        [ "$DRY" -eq 1 ] && { echo "  [simulacion] copia de las BBDD de lampp-$from a lampp-$to y sus vinculos"; return 0; }
    fi
    owner=$(data_owner "$src")
    if [ -n "$owner" ] && [ "$owner" != "$from" ]; then
        echo "lampp-$from usa las BBDD de lampp-$owner: no se copia ninguna (copialas con copiar-bd si las quieres)"
    else
        for db in $(db_names "$src"); do
            n=$((n + 1))
            echo ""
            echo "== BBDD $db =="
            link=$(linked_folder "$db" "$from")
            # (cada copia en un subproceso: copiar-bd usa trap y exit)
            if ! ( copy_database "$db" "$from" "$to" ${link:+--carpeta "$link"} ); then
                failed+=("$db")
            fi
        done
    fi
    echo ""
    if [ "$(active_dir)" == "$src" ]; then
        echo "lampp-$from era la activa: se activa lampp-$to"
        ( use_lampp "$to" ) || echo "No se ha podido activar lampp-$to: activala en Versiones de PHP"
    fi
    echo "Copiadas $((n - ${#failed[@]})) de $n BBDD de lampp-$from a lampp-$to."
    [ ${#failed[@]} -gt 0 ] && echo "No se han podido copiar: ${failed[*]} (copialas con copiar-bd)"
    echo "lampp-$from se queda como estaba: cuando compruebes que todo va bien con lampp-$to,"
    echo "desinstalala (Versiones de PHP, menu ⋮ de la version, Desinstalar)."
    [ ${#failed[@]} -eq 0 ]
}

# Hasta la 1.57.6 las copias de seguridad iban en ~/lvm-copias: la primera vez se renombra a
# ~/nexum-backups (COPIES_DIR). Solo si es una carpeta tuya (no un enlace) y aun no hay ninguna
# ~/nexum-backups: si estan las dos, no se toca ninguna
function copies_migrate() {
    local old=$HOME/lvm-copias
    [ -d "$old" ] && [ ! -L "$old" ] && [ -O "$old" ] || return 0
    if [ -e "$COPIES_DIR" ] || [ -L "$COPIES_DIR" ]; then
        return 0
    fi
    mv "$old" "$COPIES_DIR" 2> /dev/null && chmod 700 "$COPIES_DIR" 2> /dev/null
    return 0
}

# Lo que ocupa (en KB) dicho para personas: 3,4 MB
function copies_size_text() {
    awk -v n="${1:-0}" 'BEGIN {
        split("KB MB GB TB", u); i = 1
        while (n >= 1024 && i < 4) { n /= 1024; i++ }
        s = (i == 1) ? sprintf("%d %s", n, u[i]) : sprintf("%.1f %s", n, u[i])
        gsub(/\./, ",", s); print s
    }'
}

# ¿Hay en ~/nexum-backups carpetas que no son tuyas (copias que hizo root)? Lo de dentro solo se puede
# borrar con sudo
function copies_need_root() {
    [ -d "$COPIES_DIR" ] && [ ! -L "$COPIES_DIR" ] || return 1
    [ -n "$(find "$COPIES_DIR" -mindepth 1 -type d ! -user "$(id -u)" -print 2> /dev/null | head -1)" ]
}

# copias [vaciar]: sin nada, cuantos ficheros hay en ~/nexum-backups y cuanto ocupan. vaciar borra todo
# lo que hay dentro (la carpeta se queda), despues de comprobar que es una carpeta tuya y no un enlace.
# Lo que no se pueda borrar con tu usuario (copias que hizo root en una carpeta suya) se borra con
# sudo, solo dentro de esa carpeta y sin pasar a otros discos. Con --simular no se borra nada
function copies_command() {
    local dir=$COPIES_DIR files kb left
    case "$1" in
        ""|vaciar) ;;
        *) echo "Uso: nexum copias [vaciar]"; return 1 ;;
    esac
    if [ -L "$dir" ] || { [ -e "$dir" ] && [ ! -d "$dir" ]; }; then
        echo "$dir no es una carpeta (es un enlace o un fichero): no se toca"
        return 1
    fi
    if [ ! -d "$dir" ]; then
        echo "No hay copias de seguridad: $dir no existe"
        return 0
    fi
    if [ ! -O "$dir" ]; then
        echo "$dir no es tuya: no se toca"
        return 1
    fi
    files=$(find "$dir" -mindepth 1 -type f 2> /dev/null | wc -l | tr -d ' ')
    kb=$(du -sk "$dir" 2> /dev/null | cut -f1)
    if [ "$1" != vaciar ]; then
        echo "Copias de seguridad en $dir: $files $([ "$files" == 1 ] && echo fichero || echo ficheros), $(copies_size_text "${kb:-0}")"
        return 0
    fi
    if [ -z "$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)" ]; then
        echo "No hay copias de seguridad que borrar: $dir esta vacia"
        return 0
    fi
    echo "Borrando las copias de seguridad de $dir ($files $([ "$files" == 1 ] && echo fichero || echo ficheros), $(copies_size_text "${kb:-0}"))..."
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] find $dir -xdev -mindepth 1 -delete (la carpeta se queda)"
        return 0
    fi
    # (find -delete no sigue los enlaces: un enlace de dentro se borra, no lo que hay al otro lado)
    find "$dir" -xdev -mindepth 1 -delete 2> /dev/null
    left=$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)
    if [ -n "$left" ] && [ -n "$SUDO" ]; then
        echo "Algunas copias son de root: se borran con sudo (solo dentro de $dir)"
        # (se vuelve a comprobar justo antes: que sigue siendo tu carpeta y no un enlace)
        if [ -L "$dir" ] || [ ! -d "$dir" ] || [ ! -O "$dir" ]; then
            echo "$dir ha cambiado: no se borra nada mas"
            return 1
        fi
        sudo find "$dir" -xdev -mindepth 1 -delete
        left=$(find "$dir" -mindepth 1 -maxdepth 1 2> /dev/null | head -1)
    fi
    if [ -n "$left" ]; then
        echo "No se ha podido borrar todo: queda, por ejemplo, $left"
        return 1
    fi
    echo "Copias de seguridad borradas ($dir esta vacia)"
}

# copias-ficheros [si|no]: las copias de los ficheros que el programa cambia por su cuenta (el de hosts,
# los vhosts, la configuracion de los proyectos al cargarlos, lo que cambia asegurar), en ~/nexum-backups
# antes de cambiarlos. Es el fichero COPIES_FILES_FLAG: si esta, se guardan; si no (lo de partida), no.
# Sin nada, dice como esta. No pide contraseña
function copies_files_command() {
    case "$1" in
        "")
            if [ -f "$COPIES_FILES_FLAG" ]; then
                echo "Copias de los ficheros que cambia el programa: si (en ~/nexum-backups, antes de cambiarlos)"
            else
                echo "Copias de los ficheros que cambia el programa: no (con nexum copias-ficheros si, se guardan)"
            fi
            ;;
        si)
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] se crearia $COPIES_FILES_FLAG"
                return 0
            fi
            mkdir -p -m 700 "$LOG_DIR" || return 1
            # (un enlace en su lugar no se sigue: se quita y se crea el fichero)
            [ -L "$COPIES_FILES_FLAG" ] && rm -f "$COPIES_FILES_FLAG"
            [ -f "$COPIES_FILES_FLAG" ] || ( umask 077; : > "$COPIES_FILES_FLAG" ) || return 1
            echo "Copias de los ficheros que cambia el programa: si (en ~/nexum-backups, antes de cambiarlos)"
            ;;
        no)
            if [ "$DRY" -eq 1 ]; then
                echo "  [simulacion] se quitaria $COPIES_FILES_FLAG"
                return 0
            fi
            rm -f "$COPIES_FILES_FLAG" || return 1
            echo "Copias de los ficheros que cambia el programa: no"
            ;;
        *) echo "Uso: nexum copias-ficheros [si|no]"; return 1 ;;
    esac
}
# Limpieza (1.57.9): lo que el programa va dejando y se puede borrar (limpieza, gui-limpieza, limpiar
# <clave>...) y las cachés y registros de un proyecto (gui-limpiar-proyecto, limpiar-proyecto). Todo se
# mide y se borra con CLEAN_PY: sin seguir enlaces, solo dentro de su carpeta y sin pasar a otro disco.
# Lo que es de root, con sudo y con el mismo CLEAN_PY. Sin copias de seguridad: lo borrado no se recupera.
# Las claves, en el orden de la ventana
CLEAN_KEYS=(descargas copias correo registros registros-versiones caches-proyectos temporales sesiones)
CLEAN_PROJECT_KEYS=(cache registros actualizaciones)
# Los temporales, solo si llevan un dia sin cambiar (ellos y lo que tienen dentro)
CLEAN_AGE=86400

# Lo que ocupa (en bytes) dicho para personas: 3,4 MB
function clean_size_text() {
    awk -v n="${1:-0}" 'BEGIN {
        split("B KB MB GB TB", u); i = 1
        while (n >= 1024 && i < 5) { n /= 1024; i++ }
        s = (i == 1) ? sprintf("%d %s", n, u[i]) : sprintf("%.1f %s", n, u[i])
        gsub(/\./, ",", s); print s
    }'
}

function clean_files_text() {
    [ "${1:-0}" == 1 ] && echo "1 fichero" || echo "${1:-0} ficheros"
}

function clean_title() {
    case $1 in
        descargas) echo "Caché de descargas" ;;
        copias) echo "Copias de seguridad" ;;
        correo) echo "Correo de pruebas (Mailpit)" ;;
        registros) echo "Registros del programa" ;;
        registros-versiones) echo "Registros de las versiones" ;;
        caches-proyectos) echo "Cachés de los proyectos" ;;
        temporales) echo "Temporales" ;;
        sesiones) echo "Sesiones de PHP" ;;
        cache) echo "Caché" ;;
        actualizaciones) echo "Restos de actualizaciones" ;;
    esac
}

# El de una clave de un proyecto («Registros de <carpeta>», no los del programa)
function clean_project_title() {
    case $2 in
        registros) echo "Registros de $1" ;;
        *) echo "$(clean_title "$2") de $1" ;;
    esac
}

# Las carpetas de los proyectos de htdocs (sin enlaces, con un nombre valido)
function clean_projects() {
    local d n
    for d in "$HTDOCS_DIR"/*/; do
        d=${d%/} n=${d##*/}
        [ -d "$d" ] && [ ! -L "$d" ] && [[ "$n" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] && echo "$n"
    done
}

# clean_project_rules <carpeta> [<clave>...]: las reglas de CLEAN_PY de un proyecto (todas sus claves si
# no se dice ninguna). Solo las de lo que es: WordPress (wp-content y wp-config.php o wp-includes) o
# PrestaShop (sus clases o su PrestaShopBundle). Nada de wp-content/uploads (salvo los registros de
# WooCommerce, wc-logs) ni de img/ de las tiendas
function clean_project_rules() {
    local dir=$HTDOCS_DIR/$1
    shift
    local want=" ${*:-${CLEAN_PROJECT_KEYS[*]}} "
    if [ -d "$dir/wp-content" ] && { [ -f "$dir/wp-config.php" ] || [ -d "$dir/wp-includes" ]; }; then
        if [[ "$want" == *" cache "* ]]; then
            echo "cache|$dir|vaciar|wp-content/cache||"
        fi
        if [[ "$want" == *" registros "* ]]; then
            echo "registros|$dir|ficheros|wp-content|debug.log|"
            echo "registros|$dir|ficheros|wp-content/uploads/wc-logs|*.log|"
        fi
        if [[ "$want" == *" actualizaciones "* ]]; then
            echo "actualizaciones|$dir|vaciar|wp-content/upgrade||"
            echo "actualizaciones|$dir|vaciar|wp-content/upgrade-temp-backup||"
        fi
    fi
    if [ -f "$dir/classes/PrestaShopAutoload.php" ] || [ -d "$dir/src/PrestaShopBundle" ]; then
        # (los index.php que trae PrestaShop en sus carpetas de cache y de registros se quedan)
        if [[ "$want" == *" cache "* ]]; then
            echo "cache|$dir|vaciar|var/cache||"
            echo "cache|$dir|vaciar|cache/smarty/compile||index"
            echo "cache|$dir|vaciar|cache/smarty/cache||index"
            echo "cache|$dir|vaciar|cache/cachefs||index"
        fi
        if [[ "$want" == *" registros "* ]]; then
            echo "registros|$dir|vaciar|var/logs||index"
            echo "registros|$dir|vaciar|log||index"
            echo "registros|$dir|ficheros|modules/*/logs|*.log|"
            echo "registros|$dir|ficheros|modules/*/log|*.log|"
        fi
    fi
}

# clean_rules <clave>: las reglas de CLEAN_PY de una clave de limpiar (descargas, copias y correo, solo
# para medirlas: se limpian con lo suyo)
function clean_rules() {
    local d t p me
    me=$(id -u)
    case $1 in
        descargas) echo "descargas|$DL_CACHE_DIR|entradas|.|"'(?!.*[.]sha256$).+'"|solo=fich" ;;
        copias) echo "copias|$COPIES_DIR|vaciar|||" ;;
        correo) echo "correo|$MAILPIT_DATA|vaciar|||" ;;
        registros)
            # Solo estos (ninguno es un ajuste): los de las instalaciones y lo que dejan las que fallan
            # (pila-<version>-<fecha>), el de install-db, el de los proyectos sin visitas, los de los
            # proyectos de Node, el de la compilacion de la ventana del Mac y el registro de tareas de la
            # ventana (tareas/). Lo que tenga abierto una tarea o un servidor en marcha se deja; ventana.log,
            # que la ventana tiene abierto mientras esta abierta (en modo de añadir), se vacia
            [ -d "$LOG_DIR" ] && [ ! -L "$LOG_DIR" ] && [ -O "$LOG_DIR" ] || return 0
            echo "registros|$LOG_DIR|ficheros|.|instalacion-*.log|uso"
            echo "registros|$LOG_DIR|ficheros|.|install-db.log|uso"
            echo "registros|$LOG_DIR|ficheros|.|docker-reposo.log|uso"
            echo "registros|$LOG_DIR|entradas|.|pila-[A-Za-z0-9._]+-[0-9]{8}-[0-9]{6}|solo=dir,uso"
            echo "registros|$LOG_DIR|ficheros|node/proyectos|*.log|uso"
            echo "registros|$LOG_DIR|ficheros|app|compilar.log|uso"
            echo "registros|$LOG_DIR|ficheros|tareas|*.txt|uso"
            echo "registros|$LOG_DIR|truncar|.|ventana.log|"
            ;;
        registros-versiones)
            # Se vacian (Apache, PHP-FPM y MariaDB los tienen abiertos): los de Apache (logs/*_log, con los
            # de cada vhost y el de errores de PHP), el de PHP-FPM y el .err de MariaDB. Ni los .pid, ni los
            # cgisock, ni nada mas de los datos de MariaDB
            while IFS= read -r d; do
                [ -n "$d" ] || continue
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}logs|*_log|"
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}logs|php-fpm.log|"
                echo "registros-versiones|$d|truncar|${CLEAN_STACK_SUB}var/mysql|*.err|"
            done < <(clean_version_dirs)
            ;;
        caches-proyectos)
            while IFS= read -r p; do
                clean_project_rules "$p" cache | sed 's/^cache|/caches-proyectos|/'
            done < <(clean_projects)
            ;;
        temporales)
            # Los del programa que llevan un dia sin cambiar y no estan en uso (un MariaDB temporal en
            # marcha tiene su socket en /tmp/lvm-mysql-XXXX): las carpetas y ficheros lvm-* que crea en la
            # carpeta temporal y, en ~/.lvm-instalador, temporal/ (actualizar proyecto), las listas y carpetas
            # de ps-imagenes, los ficheros de mktemp de los vhosts, hosts, correo y BBDD de Docker, y las
            # descargas a medias de Mailpit, cloudflared y Node. No las copias de pasar a Docker
            # (pasar-*): si el paso falla a medias, son la unica copia de su BBDD. Ni lvm-copia.* (Mac): si
            # no se pudo mover a htdocs un proyecto del XAMPP oficial, se queda ahi y se dice
            for t in "${CLEAN_TMP_DIRS[@]}"; do
                echo "temporales|$t|entradas|.|lvm-(seguridad|mysql|conocidos|hosts|progreso|vhosts|vhosts-cert|cert|ca|pma|actualizar|mailpit|xampp|pila|icono|cliente|bash|instalar|gpg|dns|github|gh|direccion)[.-].+|edad=$CLEAN_AGE,uso"
            done
            if [ -d "$LOG_DIR" ] && [ ! -L "$LOG_DIR" ] && [ -O "$LOG_DIR" ]; then
                echo "temporales|$LOG_DIR|vaciar|temporal||edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|ps-imagenes-[a-z0-9_]{8}|solo=dir,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|(ps-imagenes-lista|vhosts-docker|hosts-docker|vhost-docker|vhosts-media|vhosts-borrar|hosts-borrar|correo)-[A-Za-z0-9]{6}|solo=fich,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|(docker|copia)-.+-[A-Za-z0-9]{6}([.]sql[.]gz)?|solo=fich,edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|.|mailpit-descarga[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|tunel|(abrir|cloudflared-descarga)[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
                echo "temporales|$LOG_DIR|entradas|node|descarga[.][A-Za-z0-9]{6}|edad=$CLEAN_AGE,uso"
            fi
            ;;
        sesiones)
            # Las de cada version: los XAMPP las guardan en su temp (session.save_path); las pilas propias
            # no lo cambian y van a la carpeta temporal, donde solo se borran las tuyas
            while IFS= read -r d; do
                [ -n "$d" ] && echo "sesiones|$d|ficheros|${CLEAN_STACK_SUB}temp|sess_*|"
            done < <(clean_version_dirs)
            for t in "${CLEAN_TMP_DIRS[@]}"; do
                echo "sesiones|$t|ficheros|.|sess_*|uid=$me"
            done
            ;;
    esac
}

# Los correos de Mailpit: los que dice su API si esta en marcha o, si no, los de su base (sin cambiarla)
function clean_mail_count() {
    local n=""
    if [ -n "$(mailpit_pid)" ]; then
        n=$(curl -fs --noproxy '*' --max-time 5 "${MAIL_UI_URL}api/v1/messages?limit=1" 2> /dev/null \
            | grep -oE '"total":[0-9]+' | head -1 | cut -d: -f2)
    fi
    if [ -z "$n" ] && [ -f "$MAILPIT_DATA/mailpit.db" ] && [ ! -L "$MAILPIT_DATA/mailpit.db" ]; then
        n=$(python3 -I -c 'import sqlite3, sys
c = sqlite3.connect("file:" + sys.argv[1] + "?mode=ro", uri=True)
print(c.execute("SELECT COUNT(*) FROM mailbox").fetchone()[0])' "$MAILPIT_DATA/mailpit.db" 2> /dev/null)
    fi
    [[ "$n" =~ ^[0-9]+$ ]] && echo "$n" || echo 0
}

# clean_measure <clave>...: L|<clave>|<bytes>|<ficheros>|<1 si hace falta root> de cada una, sin pedir
# contraseña (lo que no se puede leer con tu usuario no cuenta). Correo: sus correos y su carpeta
function clean_measure() {
    local rules=() k line out b f r
    for k in "$@"; do
        while IFS= read -r line; do
            [ -n "$line" ] && rules+=("$line")
        done < <(clean_rules "$k")
    done
    out=""
    [ ${#rules[@]} -gt 0 ] && out=$(python3 -I -c "$CLEAN_PY" medir "${rules[@]}" < /dev/null 2> /dev/null)
    for k in "$@"; do
        line=$(grep -m 1 "^L|$k|" <<< "$out")
        IFS='|' read -r _ _ b f r <<< "${line:-L|$k|0|0|0}"
        case $k in
            correo) f=$(clean_mail_count); [ "$f" -gt 0 ] || b=0; r=0 ;;
            copias) copies_need_root && r=1 ;;
        esac
        echo "L|$k|${b:-0}|${f:-0}|${r:-0}"
    done
}

function clean_valid_key() {
    local k
    for k in "${CLEAN_KEYS[@]}"; do
        [ "$k" == "$1" ] && return 0
    done
    return 1
}

# limpieza: cada cosa que se puede limpiar, con lo que ocupa y cuantos ficheros
function clean_list() {
    local k b f total=0 line
    echo "Lo que se puede limpiar (nexum limpiar <clave>...):"
    while IFS='|' read -r _ k b f _; do
        total=$((total + b))
        if [ "$f" -gt 0 ]; then
            printf '  %-20s %-30s %s · %s\n' "$k" "$(clean_title "$k")" "$(clean_size_text "$b")" "$(clean_files_text "$f")"
        else
            printf '  %-20s %-30s %s\n' "$k" "$(clean_title "$k")" "vacío"
        fi
    done < <(clean_measure "${CLEAN_KEYS[@]}")
    echo "Total: $(clean_size_text "$total"). Lo que se limpia no se puede recuperar (no se hacen copias)."
}

# ¿Hace falta root para limpiar estas claves? (para pedir la contraseña antes de empezar)
function clean_need_root() {
    local k b f r
    [ $# -gt 0 ] || return 1
    while IFS='|' read -r _ k b f r; do
        [ "${f:-0}" -gt 0 ] && [ "$r" == 1 ] && return 0
    done < <(clean_measure "$@" 2> /dev/null)
    return 1
}

# clean_run <clave> <texto> <reglas...>: limpia con CLEAN_PY como tu usuario y, si algo es de root, otra
# vez con sudo (el mismo CLEAN_PY: solo dentro de sus carpetas y sin seguir enlaces). Con --simular, solo
# dice lo que borraria
function clean_run() {
    local key=$1 title=$2 out out2 rc b f n verb=borrados
    shift 2
    [ $# -gt 0 ] || return 0
    [ "$key" == registros-versiones ] && verb=vaciados
    if [ "$DRY" -eq 1 ]; then
        out=$(python3 -I -c "$CLEAN_PY" simular "$@" < /dev/null 2> /dev/null)
        b=$(awk -F'|' '$1 == "L" { s += $3 } END { print s + 0 }' <<< "$out")
        f=$(awk -F'|' '$1 == "L" { s += $4 } END { print s + 0 }' <<< "$out")
        echo "  [simulacion] $title: se $([ "$verb" == vaciados ] && echo vaciarian || echo borrarian) $(clean_files_text "$f") ($(clean_size_text "$b"))"
        return 0
    fi
    out=$(python3 -I -c "$CLEAN_PY" limpiar "$@" < /dev/null 2>&1)
    rc=$?
    if [ $rc -eq 3 ] && [ -n "$SUDO" ]; then
        echo "$title: parte es de root, se limpia con sudo (solo dentro de sus carpetas, sin seguir enlaces)"
        out2=$(sudo python3 -I -c "$CLEAN_PY" limpiar "$@" < /dev/null 2>&1)
        rc=$?
        out=$(grep -v '^Q|' <<< "$out"; echo "$out2")
    fi
    b=$(awk -F'|' '$1 == "L" { s += $3 } END { print s + 0 }' <<< "$out")
    f=$(awk -F'|' '$1 == "L" { s += $4 } END { print s + 0 }' <<< "$out")
    echo "$title: $verb $(clean_files_text "$f") ($(clean_size_text "$b"))"
    n=$(grep '^U|' <<< "$out" | sort -u | grep -c .)
    if [ "$n" -gt 0 ]; then
        echo "  En uso, se deja$([ "$n" -gt 5 ] && echo " (y $((n - 5)) más)"):"
        grep '^U|' <<< "$out" | sort -u | head -5 | cut -d'|' -f3- | sed 's/^/    /'
    fi
    grep -vE '^[LPUQ]\|' <<< "$out" | grep . | head -5 | sed 's/^/  /'
    if [ $rc -ne 0 ]; then
        n=$(grep -c '^Q|' <<< "$out")
        echo "  No se ha podido limpiar todo$([ "$n" -gt 5 ] && echo " ($n sitios)"):"
        grep '^Q|' <<< "$out" | head -5 | cut -d'|' -f3- | sed 's/^/    /'
        return 1
    fi
    return 0
}

# Mailpit: con su API (correo vaciar). Si no esta en marcha, no se puede
function clean_mail() {
    if [ -z "$(mailpit_pid)" ] && [ "$DRY" -eq 0 ]; then
        echo "Correo de pruebas: Mailpit no esta en marcha (va con la version activa): arrancala y vuelve a limpiarlo"
        return 1
    fi
    mail_command vaciar
}

# limpiar <clave>...: limpia esas cosas (lo que esta vacio, nada). Pide sudo solo si alguna lo necesita
function clean_command() {
    local k b f r keys=() rc=0 line
    if [ $# -eq 0 ]; then
        echo "Uso: nexum limpiar <clave>... (claves: ${CLEAN_KEYS[*]}; nexum limpieza dice lo que ocupa cada una)"
        return 1
    fi
    for k in "$@"; do
        clean_valid_key "$k" || { echo "Clave no valida: $k (claves: ${CLEAN_KEYS[*]})"; return 1; }
        [[ " ${keys[*]} " == *" $k "* ]] || keys+=("$k")
    done
    echo "Limpiando (no se puede recuperar: no se hacen copias)..."
    # (lo medido, antes: dentro del bucle, sudo y lo demas no tienen que leer de una tuberia)
    local measured=() projects=() p
    mapfile -t measured < <(clean_measure "${keys[@]}")
    for line in "${measured[@]}"; do
        IFS='|' read -r _ k b f r <<< "$line"
        if [ "${f:-0}" -eq 0 ]; then
            echo "$(clean_title "$k"): nada que limpiar"
            continue
        fi
        case $k in
            descargas) downloads_command vaciar || rc=1 ;;
            copias) copies_command vaciar || rc=1 ;;
            correo) clean_mail || rc=1 ;;
            caches-proyectos)
                mapfile -t projects < <(clean_projects)
                for p in "${projects[@]}"; do
                    clean_project_key "$p" cache quiet || rc=1
                done
                ;;
            *)
                local rules=()
                while IFS= read -r line; do
                    [ -n "$line" ] && rules+=("$line")
                done < <(clean_rules "$k")
                clean_run "$k" "$(clean_title "$k")" "${rules[@]}" < /dev/null || rc=1
                ;;
        esac
    done
    [ $rc -eq 0 ] && echo "Limpieza terminada" || echo "Limpieza terminada, pero algo no se ha podido limpiar: mira lo de arriba"
    return $rc
}

# Lo que se limpiaria de un proyecto, por clave: <clave>|<bytes>|<ficheros>|<root>|<rutas separadas por ,>
function clean_project_measure() {
    local folder=$1 rules=() line out k b f r
    shift
    while IFS= read -r line; do
        [ -n "$line" ] && rules+=("$line")
    done < <(clean_project_rules "$folder" "$@")
    [ ${#rules[@]} -gt 0 ] || return 0
    out=$(python3 -I -c "$CLEAN_PY" medir "${rules[@]}" < /dev/null 2> /dev/null)
    while IFS='|' read -r _ k b f r; do
        [ -n "$k" ] || continue
        echo "$k|$b|$f|$r|$(awk -F'|' -v k="$k" '$1 == "P" && $2 == k { printf "%s%s", (n++ ? "," : ""), $3 }' <<< "$out")"
    done < <(grep '^L|' <<< "$out")
}

# gui-limpiar-proyecto <carpeta>: P|<clave>|<bytes>|<ficheros>|<rutas> de lo que tiene algo
function gui_clean_project() {
    local folder=${1%/} k b f r paths
    valid_project "$folder" > /dev/null || return 1
    while IFS='|' read -r k b f r paths; do
        [ "${f:-0}" -gt 0 ] && echo "P|$k|$b|$f|$paths"
    done < <(clean_project_measure "$folder")
    return 0
}

function clean_project_need_root() {
    local folder=${1%/} k b f r paths
    valid_project "$folder" > /dev/null 2>&1 || return 1
    shift
    while IFS='|' read -r k b f r paths; do
        [ "${f:-0}" -gt 0 ] && [ "$r" == 1 ] && return 0
    done < <(clean_project_measure "$folder" "$@")
    return 1
}

# clean_project_key <carpeta> <clave> [quiet]: limpia esa clave del proyecto. La var/cache de una tienda,
# con ps_clear_cache (vaciar-cache); lo demas, con clean_run. quiet: sin decir nada si no hay nada
function clean_project_key() {
    local folder=$1 key=$2 quiet=$3 rules=() line b f r paths
    IFS='|' read -r _ b f r paths <<< "$(clean_project_measure "$folder" "$key")"
    if [ "${f:-0}" -eq 0 ]; then
        [ -n "$quiet" ] || echo "$(clean_project_title "$folder" "$key"): nada que limpiar"
        return 0
    fi
    while IFS= read -r line; do
        [ -n "$line" ] && rules+=("$line")
    done < <(clean_project_rules "$folder" "$key")
    if [ "$key" == cache ] && [[ ",$paths," == *",var/cache,"* ]]; then
        ps_clear_cache "$folder" || return 1
        local rest=() x
        for x in "${rules[@]}"; do
            [[ "$x" == *"|vaciar|var/cache||" ]] || rest+=("$x")
        done
        rules=("${rest[@]}")
        [ "$paths" == var/cache ] && return 0
    fi
    clean_run "$key" "$(clean_project_title "$folder" "$key")" "${rules[@]}"
}

# limpiar-proyecto <carpeta> [<clave>...]: sus cachés, registros y restos de actualizaciones (sin claves,
# todo lo que tenga). Las carpetas se vacian, no se borran
function clean_project_command() {
    local folder=${1%/} k keys=() rc=0
    valid_project "$folder" || return 1
    shift
    for k in "$@"; do
        [[ " ${CLEAN_PROJECT_KEYS[*]} " == *" $k "* ]] || { echo "Clave no valida: $k (claves: ${CLEAN_PROJECT_KEYS[*]})"; return 1; }
        [[ " ${keys[*]} " == *" $k "* ]] || keys+=("$k")
    done
    [ ${#keys[@]} -gt 0 ] || keys=("${CLEAN_PROJECT_KEYS[@]}")
    if [ -z "$(clean_project_rules "$folder" "${keys[@]}")" ]; then
        echo "No hay cachés ni registros que limpiar en $folder (no es un WordPress ni una tienda PrestaShop)"
        return 0
    fi
    echo "Limpiando $folder (no se puede recuperar: no se hacen copias)..."
    for k in "${keys[@]}"; do
        clean_project_key "$folder" "$k" || rc=1
    done
    return $rc
}

# El manual (manual_command): con Linux o Mac ya elegido, y como se abre un fichero en este sistema
MANUAL_SO=linux
function manual_open() {
    xdg-open "$1" > /dev/null 2>&1 &
}
# manual [--ruta] [<capitulo>]: el manual (ayuda/), que va dentro de este mismo script (al final, después
# del exit, en base64: un solo fichero, también al actualizar). Se saca a ~/.lvm-instalador/ayuda la
# primera vez y cada vez que cambia (su huella), y se abre en el navegador en <capitulo> (proyectos,
# limpieza…), con Linux o Mac ya elegido. --ruta: solo dice qué abrir (lo abre la ventana).
# El navegador no siempre respeta lo de detrás de # al abrir un fichero: se abre abrir.html, que lleva a
# index.html?so=…#<capitulo>
MANUAL_PY='
import base64, hashlib, io, os, shutil, sys, tarfile, tempfile
script, dest = sys.argv[1], sys.argv[2]
lines, inside = [], False
with open(script, encoding="utf-8") as f:
    for line in f:
        line = line.rstrip("\n")
        if line == ": <<'"'"'NEXUM_MANUAL'"'"'":
            inside = True
        elif inside and line == "NEXUM_MANUAL":
            break
        elif inside:
            lines.append(line)
if not lines:
    sys.exit("Este script no lleva el manual dentro")
data = "".join(lines).encode()
mark = hashlib.sha256(data).hexdigest()
try:
    with open(os.path.join(dest, ".huella")) as f:
        if f.read().strip() == mark:
            sys.exit(0)
except OSError:
    pass
os.umask(0o077)
parent = os.path.dirname(dest)
os.makedirs(parent, mode=0o700, exist_ok=True)
if os.path.islink(dest):
    sys.exit("%s es un enlace: no se toca" % dest)
new = tempfile.mkdtemp(prefix=".ayuda-", dir=parent)
try:
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(data)), mode="r:") as tar:
        for m in tar:
            parts = m.name.split("/")
            # (solo ficheros y carpetas, dentro de la suya: nada de rutas absolutas, .. ni enlaces)
            if m.name.startswith("/") or ".." in parts or not (m.isfile() or m.isdir()):
                sys.exit("El manual trae algo que no se saca: %s" % m.name)
            path = os.path.join(new, *parts)
            if m.isdir():
                os.makedirs(path, mode=0o700, exist_ok=True)
                continue
            os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
            with tar.extractfile(m) as src, open(path, "wb") as out:
                shutil.copyfileobj(src, out)
    with open(os.path.join(new, ".huella"), "w") as f:
        f.write(mark + "\n")
    old = None
    if os.path.isdir(dest):
        old = tempfile.mkdtemp(prefix=".ayuda-vieja-", dir=parent)
        os.rename(dest, os.path.join(old, "ayuda"))
    os.rename(new, dest)
    new = None
    if old:
        shutil.rmtree(old, ignore_errors=True)
finally:
    if new:
        shutil.rmtree(new, ignore_errors=True)
'

function manual_command() {
    local only="" chapter="" dir=$LOG_DIR/ayuda
    [ "$1" == "--ruta" ] && only=1 && shift
    chapter=${1:-}
    if ! [[ "$chapter" =~ ^[a-z][a-z0-9-]{0,40}$ ]]; then
        [ -n "$chapter" ] && echo "Capitulo no valido: $chapter (se abre el principio)"
        chapter=inicio
    fi
    python3 -I -c "$MANUAL_PY" "$SELF" "$dir" || { echo "No se ha podido sacar el manual a $dir"; return 1; }
    ( umask 077
      printf '<!doctype html>\n<meta charset="utf-8">\n<title>Manual de Nexum Dev Stack</title>\n<meta http-equiv="refresh" content="0; url=index.html?so=%s#%s">\n<script>location.replace("index.html?so=%s#%s")</script>\n' \
          "$MANUAL_SO" "$chapter" "$MANUAL_SO" "$chapter" > "$dir/abrir.html" ) || return 1
    if [ -n "$only" ]; then
        echo "$dir/abrir.html"
        return 0
    fi
    echo "Abriendo el manual: $dir/index.html"
    manual_open "$dir/abrir.html"
}
# Limpieza en Linux: las versiones son /opt/lampp-* (en las pruebas, las de LVM_PRUEBA), con sus logs, var/mysql
# y temp sin subcarpeta; la carpeta temporal, /tmp y la tuya (TMPDIR) si es otra
CLEAN_STACK_SUB=""
CLEAN_TMP_DIRS=(/tmp)
if [ -n "$TEST_DIR" ]; then
    CLEAN_TMP_DIRS=("$TEST_DIR/tmp")
elif [ -n "${TMPDIR:-}" ] && [ -d "$TMPDIR" ] && [ ! -L "${TMPDIR%/}" ] && [ -O "$TMPDIR" ]; then
    [ "$(cd "$TMPDIR" && pwd -P)" == "/tmp" ] || CLEAN_TMP_DIRS+=("${TMPDIR%/}")
fi

function clean_version_dirs() {
    if [ -n "$TEST_DIR" ]; then
        find "$TEST_DIR" -maxdepth 1 -type d -name "lampp-*" 2> /dev/null | sort -V
    else
        lampp_dirs
    fi
}

if [ "$1" == "--simular" ]; then
    DRY=1
    shift
fi

# (no en --simular, ni en las pruebas, LVM_PRUEBA, ni al pedir solo la version o las novedades, como
# hace el empaquetador: tu carpeta se queda como esta)
case "${1:-}" in
    version|--version|-v|acerca|about|novedades|-h|--help|--ayuda|construir-pila) ;;
    *) [ "$DRY" -eq 0 ] && [ -z "$TEST_DIR" ] && copies_migrate ;;
esac

for cmd in curl python3; do
    command -v $cmd > /dev/null || { echo "Falta el comando $cmd. Instalalo con: sudo apt install $cmd"; exit 1; }
done

# Copias de bases, configuraciones de proyectos y registros: solo para tu usuario
for dir in "$COPIES_DIR" "$LOG_DIR"; do
    if [ -d "$dir" ] && [ -O "$dir" ] && [ ! -L "$dir" ]; then
        chmod 700 "$dir" 2> /dev/null
        find "$dir" -maxdepth 2 -type f -user "$(id -u)" -perm /077 -exec chmod go-rwx {} + 2> /dev/null
    fi
done


# ===========================================================================
# phpMyAdmin: actualizar el de una version
# ===========================================================================
# phpMyAdmin que admite cada PHP: la 5.2 (la ultima) desde PHP 7.2.5, la 5.1.4 desde la 7.1.3 y la
# 4.9.11 antes. Los XAMPP traen la 4.9.2, 5.2.0 o 5.2.1, con fallos de seguridad corregidos despues.
function pma_for_php() {
    local php=$1
    if [ "$(printf '%s\n%s\n' 7.2.5 "$php" | sort -V | head -1)" == 7.2.5 ]; then
        latest_pma
    elif [ "$(printf '%s\n%s\n' 7.1.3 "$php" | sort -V | head -1)" == 7.1.3 ]; then
        echo 5.1.4
    else
        echo 4.9.11
    fi
}

# Huella sha256 del phpMyAdmin <version>: las que pone el gestor van fijadas aqui; otra, la que
# publica phpMyAdmin (del mismo servidor que el fichero: solo protege de descargas a medias)
function pma_sum() {
    case $1 in
        5.2.3) echo 57881348297c4412f86c410547cf76b4d8a236574dd2c6b7d6a2beebe7fc44e3 ;;
        5.1.4) echo 3230cf0e004b6284c70e0cb26064a8666b271749ef54236d035104a972822999 ;;
        4.9.11) echo 2b14737a2220e5ac9d2eaf683df6b56ebaa490d038ee980367cb4db909a57923 ;;
        *) curl -q --proto =https --proto-redir =https -fsSL "https://files.phpmyadmin.net/phpMyAdmin/$1/phpMyAdmin-$1-all-languages.tar.xz.sha256" 2> /dev/null | grep -oE '^[0-9a-f]{64}' ;;
    esac
}

# Version de phpMyAdmin instalada en <carpeta de phpmyadmin> (vacio si no se sabe)
function pma_installed() {
    local v
    v=$(grep -hoE "(VERSION = |PMA_VERSION', )'[0-9.]+'" "$1/libraries/classes/Version.php" \
        "$1/libraries/classes/Config.php" "$1/libraries/Config.php" 2> /dev/null | head -1 | grep -oE "[0-9][0-9.]+")
    [ -z "$v" ] && v=$(grep -rhoE "(VERSION = |PMA_VERSION', )'[0-9.]+'" "$1/libraries" 2> /dev/null | head -1 | grep -oE "[0-9][0-9.]+")
    echo "$v"
}

# actualizar-phpmyadmin <version>: pone el phpMyAdmin mas nuevo que admite su PHP (comprobado con su
# sha256), con la configuracion de antes (config.inc.php) y una clave de cookies nueva si la de
# XAMPP es la de fabrica. El anterior queda en phpmyadmin.anterior.
function update_pma() {
    local FETCH_FRESH=1
    local version=$1 root dir php cur want tmp sum new grp d rc=0
    if [ "$version" == "--todas" ]; then
        for d in $(lampp_dirs); do
            [ -f "$d/phpmyadmin/config.inc.php" ] || continue
            update_pma "${d#/opt/lampp-}" || rc=1
        done
        return $rc
    fi
    valid_version_name "$version" && [ -d "/opt/lampp-$version" ] \
        || { echo "No existe la version $version de lampp en el sistema"; return 1; }
    root="/opt/lampp-$version"
    dir=$root/phpmyadmin
    if [ ! -f "$dir/config.inc.php" ]; then
        echo "$version no tiene phpMyAdmin con su configuracion ($dir/config.inc.php)"
        return 1
    fi
    php=$(php_version "$root")
    cur=$(pma_installed "$dir")
    want=$(pma_for_php "$php")
    [[ "$want" =~ ^[0-9]+(\.[0-9]+){1,3}$ ]] || { echo "No se ha podido saber que phpMyAdmin poner"; return 1; }
    if [ -n "$cur" ] && [ "$(printf '%s\n%s\n' "$want" "$cur" | sort -V | tail -1)" == "$cur" ]; then
        echo "phpMyAdmin de $version ya esta al dia ($cur, PHP $php)"
        return 0
    fi
    task_plan "Actualizando phpMyAdmin de $version" "Descargar y comprobar phpMyAdmin $want" "Preparar su configuración" "Cambiar la carpeta"
    echo "phpMyAdmin de $version: ${cur:-version antigua} -> $want (PHP $php)"
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] descarga, comprobacion sha256 y cambio de $dir (el anterior en phpmyadmin.anterior)"
        return 0
    fi
    # Antes de cambiar nada como root: la carpeta de la version tiene que ser de root (y en
    # Linux, /opt tambien), no un enlace que lleve a otro sitio
    vhosts_root > /dev/null
    if [ -L "$root" ] || [ -L "$dir" ] || [ "$(stat -c %u /opt)" != 0 ] || [ "$(stat -c %u "$root")" != 0 ]; then
        echo "No se cambia phpMyAdmin: /opt o $root no son del administrador (nexum asegurar --todas)"
        return 1
    fi
    task_step
    tmp=$(mktemp -d "${TMPDIR:-/tmp}/lvm-pma.XXXXXX") || return 1
    sum=$(pma_sum "$want")
    if ! download_signed "https://files.phpmyadmin.net/phpMyAdmin/$want/phpMyAdmin-$want-all-languages.tar.xz" "$tmp/pma.tar.xz" "$sum" "$GPG_FPR_PMA" \
            || ! tar -xJf "$tmp/pma.tar.xz" -C "$tmp"; then
        rm -rf "$tmp"
        return 1
    fi
    new=$tmp/phpMyAdmin-$want-all-languages
    [ -d "$new" ] || { rm -rf "$tmp"; echo "El paquete de phpMyAdmin no es el esperado"; return 1; }
    # La configuracion de antes; la clave de las cookies de XAMPP es la misma en todos (xampp)
    task_step
    cp "$dir/config.inc.php" "$new/config.inc.php" || { rm -rf "$tmp"; return 1; }
    python3 -I - "$new/config.inc.php" <<'PY'
import re, secrets, string, sys
path = sys.argv[1]
text = open(path, encoding="utf-8", errors="surrogateescape").read()
m = re.search(r"""\$cfg\[\s*['"]blowfish_secret['"]\s*\]\s*=\s*(['"])(.*?)\1""", text)
if m is None or len(m.group(2)) < 32:
    key = "".join(secrets.choice(string.ascii_letters + string.digits) for _ in range(32))
    assign = "$cfg['blowfish_secret'] = '%s'" % key
    if m:
        text = text[:m.start()] + assign + text[m.end():]
    else:
        text = text.rstrip() + "\n" + assign + "; /* lvm-instalador */\n"
    open(path, "w", encoding="utf-8", errors="surrogateescape").write(text)
PY
    grp=$(stat -c %G "$dir/tmp" 2> /dev/null || echo root)
    # phpMyAdmin no trae enlaces: uno en la carpeta (que es tuya hasta que root la copia) seria de
    # otro programa. Se mira otra vez en la copia, ya de root, y tmp la crea root vacia (si fuera un
    # enlace, root cambiaria el dueño y los permisos de lo que apunta)
    if [ -n "$(find "$new" \( -type l -o -type f -links +1 \) -print -quit)" ]; then
        rm -rf "$tmp"
        echo "El phpMyAdmin descargado tiene enlaces (no deberia): no se cambia nada"
        return 1
    fi
    task_step
    if ! { sudo rm -rf "$root/phpmyadmin.anterior" && sudo mv "$dir" "$root/phpmyadmin.anterior"; }; then
        echo "No se ha podido apartar $dir: no se cambia nada"
        rm -rf "$tmp"
        return 1
    fi
    if ! { sudo cp -R "$new" "$dir" \
            && [ -z "$(sudo find "$dir" -type l -print -quit)" ] \
            && sudo chown -R root:root "$dir" \
            && sudo chmod -R go-w "$dir" \
            && sudo rm -rf "$dir/tmp" \
            && sudo install -d -o 0 -g "$grp" -m 775 "$dir/tmp"; }; then
        sudo rm -rf "$dir" && sudo mv "$root/phpmyadmin.anterior" "$dir"
        echo "No se ha podido cambiar $dir: se ha dejado el phpMyAdmin anterior"
        rm -rf "$tmp"
        return 1
    fi
    rm -rf "$tmp"
    if [ "$(active_dir)" == "/opt/lampp-$version" ] && [ -f /opt/lampp/logs/httpd.pid ]; then
        run sudo /opt/lampp/lampp reloadapache > /dev/null
    fi
    echo "phpMyAdmin $want instalado en $version"
}

# Proyectos de Node (Astro, Next, Nuxt, SvelteKit, Vite...): carpetas de htdocs con su package.json, cada
# una con su propio servidor en 127.0.0.1, siempre con tu usuario (nunca root ni sudo). En Desarrollo, con
# el servidor del proyecto; Compilado, como en produccion: es el unico que se comparte por el tunel, porque
# el proxy no deja pasar ficheros ocultos (/node_modules/.vite) y asi el codigo fuente no sale del equipo.
NODE_DIR=$LOG_DIR/node
NODE_RUN_DIR=$NODE_DIR/proyectos
NODE_DEFAULT_MAJOR=26
NODE_PORT_FROM=4321
NODE_PORT_TO=4399

# P|carpeta|tipo|parado o marcha|modo|direccion|Node que pide (26, o 24+ si vale de ahi en adelante)|
# dependencias instaladas (1/0)|scripts (d de dev, b de build, s de start). Con una carpeta, solo esa.
# No son de Node las webs de PHP que usan npm para sus estilos (wp-config.php, index.php, artisan)
NODE_LIST_PY='
import json, os, re, subprocess, sys
htdocs, run = sys.argv[1:3]
only = sys.argv[3] if len(sys.argv) > 3 else None
KINDS = (("astro", "Astro"), ("next", "Next"), ("nuxt", "Nuxt"), ("@sveltejs/kit", "SvelteKit"), ("vite", "Vite"))


def need(d, pkg):
    for name in (".nvmrc", ".node-version"):
        try:
            with open(os.path.join(d, name), encoding="utf-8") as f:
                m = re.match(r"v?(\d+)", f.read(40).strip())
        except (OSError, UnicodeError):
            m = None
        if m:
            return m.group(1)
    engines = pkg.get("engines")
    text = str(engines.get("node") or "") if isinstance(engines, dict) else ""
    m = re.search(r"\d+", text)
    if not m:
        return ""
    return m.group(0) + ("+" if text.strip().startswith(">") else "")


def running(name):
    conf = {}
    try:
        with open(os.path.join(run, name + ".conf"), encoding="utf-8") as f:
            for line in f:
                k, _, v = line.rstrip("\n").partition("=")
                conf[k] = v
        out = subprocess.run(["ps", "-o", "lstart=", "-p", conf["PID"]], capture_output=True, text=True,
                             env={"LC_ALL": "C", "PATH": "/usr/bin:/bin"}, timeout=5).stdout.strip()
    except (OSError, KeyError, ValueError, subprocess.SubprocessError):
        return None
    return conf if out and out == conf.get("LSTART") else None


try:
    names = [only] if only else sorted(os.listdir(htdocs), key=str.lower)
except OSError:
    names = []
for name in names:
    d = os.path.join(htdocs, name)
    if not re.fullmatch(r"[A-Za-z0-9_][A-Za-z0-9 ._-]*", name) or os.path.islink(d):
        continue
    if any(os.path.exists(os.path.join(d, f)) for f in ("wp-config.php", "index.php", "artisan")):
        continue
    try:
        with open(os.path.join(d, "package.json"), encoding="utf-8") as f:
            pkg = json.load(f)
    except (OSError, ValueError):
        continue
    if not isinstance(pkg, dict):
        continue
    deps = {}
    for key in ("dependencies", "devDependencies"):
        if isinstance(pkg.get(key), dict):
            deps.update(pkg[key])
    scripts = pkg.get("scripts") if isinstance(pkg.get("scripts"), dict) else {}
    kind = next((label for dep, label in KINDS if dep in deps), "")
    if not kind and not ("dev" in scripts or "start" in scripts):
        continue
    conf = running(name)
    print("|".join(("P", name, kind or "Node", "marcha" if conf else "parado", conf.get("MODE", "") if conf else "",
                    "http://127.0.0.1:%s" % conf["PORT"] if conf and conf.get("PORT", "").isdigit() else "",
                    need(d, pkg), "1" if os.path.isdir(os.path.join(d, "node_modules")) else "0",
                    ("d" if "dev" in scripts else "") + ("b" if "build" in scripts else "") + ("s" if "start" in scripts else ""))))
'

function node_lines() {
    python3 -I -c "$NODE_LIST_PY" "$HTDOCS_DIR" "$NODE_RUN_DIR" "$@"
}

function gui_node() {
    node_lines | tr -d '\000-\011\013-\037'
}

# La carpeta bin de un Node que valga para lo que pide el proyecto (26, 24+ o nada: el mas nuevo de los
# que coincidan). De Nexum, de nvm o el del sistema; los nuevos, primero.
function node_find() {
    local want=$1 min=${1%+} d v major key best="" best_key=-1 sys
    for d in "$NODE_DIR"/v*/bin "$HOME"/.nvm/versions/node/v*/bin; do
        [ -x "$d/node" ] && [ -x "$d/npm" ] || continue
        v=$(basename "$(dirname "$d")")
        [[ "$v" =~ ^v([0-9]+)\.([0-9]+)\.([0-9]+)$ ]] || continue
        major=${BASH_REMATCH[1]}
        key=$(( major * 1000000 + BASH_REMATCH[2] * 1000 + BASH_REMATCH[3] ))
        if [ -n "$want" ]; then
            if [[ "$want" == *+ ]]; then [ "$major" -ge "$min" ] || continue; else [ "$major" -eq "$min" ] || continue; fi
        fi
        [ "$key" -gt "$best_key" ] && { best=$d; best_key=$key; }
    done
    if [ -z "$best" ]; then
        sys=$(command -v node 2> /dev/null)
        if [ -n "$sys" ] && [ -x "$(dirname "$sys")/npm" ]; then
            major=$("$sys" -v 2> /dev/null | sed -E 's/^v([0-9]+).*/\1/')
            if [[ "$major" =~ ^[0-9]+$ ]] && { [ -z "$want" ] \
                    || { [[ "$want" == *+ ]] && [ "$major" -ge "$min" ]; } || [ "$major" -eq "${min:-0}" ]; }; then
                best=$(dirname "$sys")
            fi
        fi
    fi
    [ -n "$best" ] && echo "$best"
}

# Descarga Node <mayor> de nodejs.org en ~/.lvm-instalador/node y lo comprueba con su lista de sumas sha256
function node_install() {
    local major=$1 base=https://nodejs.org/dist os arch sums name sha got tmp top version tls=(--proto =https --tlsv1.2)
    [[ "$major" =~ ^[0-9]+$ ]] || { echo "Versión de Node no válida: $major"; return 1; }
    case "$(uname -s)" in
        Darwin) os=darwin ;;
        Linux) os=linux ;;
        *) echo "Sistema sin Node descargable: $(uname -s)"; return 1 ;;
    esac
    case "$(uname -m)" in
        arm64|aarch64) arch=arm64 ;;
        x86_64|amd64) arch=x64 ;;
        *) echo "Procesador sin Node descargable: $(uname -m)"; return 1 ;;
    esac
    # (en las pruebas, de una carpeta local)
    [ -n "$TEST_DIR" ] && [ -n "$LVM_NODE_BASE" ] && { base=$LVM_NODE_BASE; tls=(); }
    echo "Descargando Node $major de nodejs.org ($os, $arch)..."
    mkdir -p -m 700 "$NODE_DIR" || return 1
    tmp=$(mktemp -d "$NODE_DIR/descarga.XXXXXX") || return 1
    if ! sums=$(curl -q -fsSL "${tls[@]}" --retry 2 --max-time 60 "$base/latest-v$major.x/SHASUMS256.txt"); then
        rm -rf "$tmp"
        echo "No se ha podido leer la lista de Node $major en nodejs.org"
        return 1
    fi
    name=$(awk -v rx="^node-v$major\\\\.[0-9]+\\\\.[0-9]+-$os-$arch\\\\.tar\\\\.gz$" '$2 ~ rx { print $2; exit }' <<< "$sums")
    sha=$(awk -v n="$name" '$2 == n { print $1; exit }' <<< "$sums")
    if [ -z "$name" ] || [[ ! "$sha" =~ ^[0-9a-f]{64}$ ]]; then
        rm -rf "$tmp"
        echo "Node $major no tiene paquete para $os $arch"
        return 1
    fi
    if ! curl -q -fsSL "${tls[@]}" --retry 2 --max-time 900 -o "$tmp/node.tar.gz" "$base/latest-v$major.x/$name"; then
        rm -rf "$tmp"
        echo "No se ha podido descargar $name"
        return 1
    fi
    if command -v sha256sum > /dev/null; then got=$(sha256sum "$tmp/node.tar.gz" | cut -d' ' -f1); else got=$(shasum -a 256 "$tmp/node.tar.gz" | cut -d' ' -f1); fi
    if [ "$got" != "$sha" ]; then
        rm -rf "$tmp"
        echo "La descarga de Node no coincide con su suma sha256 (${got:-ninguna}): no se instala."
        return 1
    fi
    top=${name%.tar.gz}
    version=${top#node-}
    version=${version%%-*}
    if ! tar -xzf "$tmp/node.tar.gz" -C "$tmp" "$top" 2> /dev/null || [ ! -x "$tmp/$top/bin/node" ]; then
        rm -rf "$tmp"
        echo "El paquete de Node no trae su programa: no se instala."
        return 1
    fi
    rm -rf "${NODE_DIR:?}/$version"
    mv "$tmp/$top" "$NODE_DIR/$version" || { rm -rf "$tmp"; return 1; }
    rm -rf "$tmp"
    echo "Node $version instalado en $NODE_DIR"
}

# El pid del servidor de un proyecto, si sigue siendo aquel (misma hora de arranque)
function node_pid() {
    local conf=$NODE_RUN_DIR/$1.conf pid start
    [ -f "$conf" ] || return 1
    pid=$(sed -n 's/^PID=//p' "$conf")
    start=$(sed -n 's/^LSTART=//p' "$conf")
    [[ "$pid" =~ ^[0-9]+$ ]] && [ -n "$start" ] || return 1
    [ "$(LC_ALL=C ps -o lstart= -p "$pid" 2> /dev/null | sed -E 's/^ +//; s/ +$//')" == "$start" ] || return 1
    echo "$pid"
}

function node_free_port() {
    python3 -I -c '
import socket, sys
for port in range(int(sys.argv[1]), int(sys.argv[2]) + 1):
    s = socket.socket()
    try:
        s.bind(("127.0.0.1", port))
    except OSError:
        continue
    finally:
        s.close()
    print(port)
    break
' "$NODE_PORT_FROM" "$NODE_PORT_TO"
}

# Instala lo que le falte: lo pide su fichero de bloqueo. Los scripts de sus paquetes se ejecutan con tu usuario
function node_deps() {
    local dir=$1 bin=$2 lock=""
    shift 2
    for lock in package-lock.json pnpm-lock.yaml yarn.lock; do
        [ -f "$dir/$lock" ] && break
        lock=""
    done
    if [ -d "$dir/node_modules" ] && { [ -z "$lock" ] || [ ! "$dir/$lock" -nt "$dir/node_modules" ]; }; then
        echo "Dependencias: ya están instaladas"
        return 0
    fi
    echo "Instalando las dependencias..."
    case "$lock" in
        package-lock.json) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" ci --no-audit --no-fund ) ;;
        pnpm-lock.yaml) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --yes pnpm install --frozen-lockfile ) ;;
        yarn.lock) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --yes yarn install --frozen-lockfile ) ;;
        *) ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" install --no-audit --no-fund ) ;;
    esac || { echo "No se han podido instalar las dependencias"; return 1; }
    touch "$dir/node_modules"
}

# Astro con un adaptador de un alojamiento (Vercel, Netlify, Cloudflare) no se puede servir en este equipo:
# se compila con el de Node, sin tocar su configuracion ni su package.json (todo dentro de node_modules)
function node_build_astro() {
    local dir=$1 bin=$2 conf="" c
    shift 2
    for c in astro.config.mjs astro.config.ts astro.config.mts astro.config.js astro.config.cjs; do
        [ -f "$dir/$c" ] && { conf=$c; break; }
    done
    if [ -z "$conf" ] || ! grep -qE "@astrojs/(vercel|netlify|cloudflare)" "$dir/$conf"; then
        ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --no-install astro build )
        return
    fi
    if [ ! -f "$dir/node_modules/@astrojs/node/package.json" ]; then
        if [ -f "$dir/pnpm-lock.yaml" ] || [ -f "$dir/yarn.lock" ]; then
            echo "Este proyecto usa un adaptador de alojamiento: añade @astrojs/node a sus dependencias para compilarlo aquí."
            return 1
        fi
        ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npm" install --no-save --no-audit --no-fund @astrojs/node ) || return 1
    fi
    printf "import base from '../%s';\nimport node from '@astrojs/node';\nexport default { ...base, adapter: node({ mode: 'standalone' }) };\n" "$conf" \
        > "$dir/node_modules/.nexum-astro.config.mjs" || return 1
    echo "(compilando con @astrojs/node en lugar de su adaptador de alojamiento; el proyecto no cambia)"
    ( cd "$dir" && /usr/bin/env -i "$@" "$bin/npx" --no-install astro build --config node_modules/.nexum-astro.config.mjs )
}

# Lo que deja el servidor en marcha, en NODE_CMD: node_command <carpeta> <tipo> <modo> <scripts> <bin> <puerto>
NODE_CMD=()
function node_command() {
    local dir=$1 kind=$2 mode=$3 scripts=$4 bin=$5 port=$6 root
    NODE_CMD=()
    if [ "$mode" == desarrollo ]; then
        case "$kind" in
            Astro) NODE_CMD=("$bin/npx" --no-install astro dev --host 127.0.0.1 --port "$port") ;;
            Next) NODE_CMD=("$bin/npx" --no-install next dev -H 127.0.0.1 -p "$port") ;;
            Nuxt) NODE_CMD=("$bin/npx" --no-install nuxt dev --host 127.0.0.1 --port "$port") ;;
            SvelteKit|Vite) NODE_CMD=("$bin/npx" --no-install vite --host 127.0.0.1 --port "$port" --strictPort) ;;
            *) if [[ "$scripts" == *d* ]]; then NODE_CMD=("$bin/npm" run dev); elif [[ "$scripts" == *s* ]]; then NODE_CMD=("$bin/npm" start); fi ;;
        esac
    else
        case "$kind" in
            Astro)
                if [ -f "$dir/dist/server/entry.mjs" ]; then
                    NODE_CMD=("$bin/node" dist/server/entry.mjs)
                else
                    root=dist
                    [ -d "$dir/dist/client" ] && root=dist/client
                    NODE_CMD=(python3 -I -m http.server --bind 127.0.0.1 --directory "$root" "$port")
                fi
                ;;
            Next) NODE_CMD=("$bin/npx" --no-install next start -H 127.0.0.1 -p "$port") ;;
            Nuxt) NODE_CMD=("$bin/node" .output/server/index.mjs) ;;
            SvelteKit|Vite) NODE_CMD=("$bin/npx" --no-install vite preview --host 127.0.0.1 --port "$port" --strictPort) ;;
            *) [[ "$scripts" == *s* ]] && NODE_CMD=("$bin/npm" start) ;;
        esac
    fi
    [ "${#NODE_CMD[@]}" -gt 0 ]
}

# node-arrancar <carpeta> [desarrollo|compilado]
function node_start() {
    local folder=${1%/} mode=${2:-desarrollo} dir line kind state need deps scripts bin port log conf pid n x steps=() e=()
    if [ "${EUID:-$(id -u)}" -eq 0 ]; then
        echo "Los proyectos de Node no se arrancan como root."
        return 1
    fi
    [[ "$mode" =~ ^(desarrollo|compilado)$ ]] || { echo "El modo es desarrollo o compilado"; return 1; }
    valid_project "$folder" || return 1
    dir=$HTDOCS_DIR/$folder
    line=$(node_lines "$folder")
    if [ -z "$line" ]; then
        echo "$folder no es un proyecto de Node"
        return 1
    fi
    IFS='|' read -r x x kind state x x need deps scripts <<< "$line"
    if [ "$mode" == compilado ] && [ "$kind" == Node ] && [[ "$scripts" != *s* ]]; then
        echo "$folder no tiene un script start: no se sabe cómo servirlo compilado"
        return 1
    fi
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] $folder ($kind, $mode): Node ${need:-el que haya}, dependencias y servidor en 127.0.0.1"
        return 0
    fi
    steps=("Preparar Node ${need:-}" "Instalar las dependencias")
    [ "$mode" == compilado ] && steps+=("Compilar el proyecto")
    steps+=("Arrancar el servidor")
    task_plan "Arrancando $folder" "${steps[@]}"
    [ "$state" == marcha ] && node_stop "$folder" > /dev/null

    task_step
    bin=$(node_find "$need")
    if [ -z "$bin" ]; then
        x=${need%+}
        node_install "${x:-$NODE_DEFAULT_MAJOR}" || return 1
        bin=$(node_find "$need")
        [ -n "$bin" ] || { echo "No se encuentra el Node recién instalado"; return 1; }
    fi
    echo "Node $("$bin/node" -v) ($bin)"
    port=$(node_free_port)
    [ -n "$port" ] || { echo "No hay ningún puerto libre entre $NODE_PORT_FROM y $NODE_PORT_TO"; return 1; }
    e=("HOME=$HOME" "USER=${USER:-$(id -un)}" "LANG=${LANG:-es_ES.UTF-8}" "TERM=dumb" "CI=1"
       "PATH=$bin:/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin" "HOST=127.0.0.1" "PORT=$port" "NO_COLOR=1"
       "ASTRO_TELEMETRY_DISABLED=1" "NEXT_TELEMETRY_DISABLED=1")

    task_step
    node_deps "$dir" "$bin" "${e[@]}" || return 1

    if [ "$mode" == compilado ]; then
        task_step
        echo "Compilando..."
        if [ "$kind" == Astro ]; then
            node_build_astro "$dir" "$bin" "${e[@]}"
        elif [[ "$scripts" == *b* ]]; then
            ( cd "$dir" && /usr/bin/env -i "${e[@]}" "$bin/npm" run build )
        fi || { echo "No se ha podido compilar $folder"; return 1; }
    fi

    task_step
    node_command "$dir" "$kind" "$mode" "$scripts" "$bin" "$port" || { echo "$folder no tiene un script dev ni start"; return 1; }
    mkdir -p -m 700 "$NODE_RUN_DIR" || return 1
    log=$NODE_RUN_DIR/$folder.log conf=$NODE_RUN_DIR/$folder.conf
    : > "$log" && chmod 600 "$log" || return 1
    # (en su propia sesion, para pararlo con todos sus hijos y que siga al cerrar la ventana)
    ( cd "$dir" && exec python3 -I -c 'import os, sys
os.setsid()
os.execv("/usr/bin/env", ["env", "-i"] + sys.argv[1:])' "${e[@]}" "${NODE_CMD[@]}" >> "$log" 2>&1 < /dev/null ) &
    pid=$!
    ( umask 077; printf 'PID=%s\nLSTART=%s\nPORT=%s\nMODE=%s\n' "$pid" \
        "$(LC_ALL=C ps -o lstart= -p "$pid" 2> /dev/null | sed -E 's/^ +//; s/ +$//')" "$port" "$mode" > "$conf" ) || return 1
    echo "Arrancando el servidor en http://127.0.0.1:$port ..."
    for n in $(seq 360); do
        if ! kill -0 "$pid" 2> /dev/null; then
            rm -f "$conf"
            echo "El servidor de $folder se ha parado al arrancar. Lo último que ha dicho:"
            tail -20 "$log" | sed 's/^/  /'
            return 1
        fi
        curl -q -s -o /dev/null --noproxy '*' --max-time 2 "http://127.0.0.1:$port/" && break
        sleep 0.5
    done
    if [ "$n" -ge 360 ]; then
        node_stop "$folder" > /dev/null
        echo "El servidor de $folder no responde en http://127.0.0.1:$port tras 3 minutos: se para. Lo último que ha dicho:"
        tail -20 "$log" | sed 's/^/  /'
        return 1
    fi
    echo "$folder en marcha ($mode): http://127.0.0.1:$port"
    echo "URL|http://127.0.0.1:$port"
}

# node-parar <carpeta>: el servidor con todos sus hijos y, si se esta compartiendo, tambien su tunel (ese
# puerto podria acabar siendo de otro proyecto)
function node_stop() {
    local folder=${1%/} pid conf=$NODE_RUN_DIR/${1%/}.conf port n
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || { echo "Carpeta no válida: $folder"; return 1; }
    if [ "$DRY" -eq 1 ]; then
        echo "  [simulacion] se para $folder"
        return 0
    fi
    pid=$(node_pid "$folder")
    if [ -z "$pid" ]; then
        rm -f "$conf"
        echo "$folder no está en marcha"
        return 0
    fi
    port=$(sed -n 's/^PORT=//p' "$conf")
    if [[ "$port" =~ ^[0-9]+$ ]] && [ -f "$TUNNEL_STATE" ] && grep -qF "\"target\": \"http://127.0.0.1:$port\"" "$TUNNEL_STATE"; then
        tunnel_close > /dev/null
        echo "Túnel cerrado: compartía este proyecto"
    fi
    kill -TERM -- "-$pid" 2> /dev/null
    for n in $(seq 20); do
        kill -0 -- "-$pid" 2> /dev/null || break
        sleep 0.25
    done
    kill -KILL -- "-$pid" 2> /dev/null
    rm -f "$conf"
    echo "$folder parado"
}

# node-registro <carpeta>: lo ultimo que ha dicho su servidor
function node_log() {
    local folder=${1%/} log=$NODE_RUN_DIR/${1%/}.log
    [[ "$folder" =~ ^[A-Za-z0-9_][A-Za-z0-9\ ._-]*$ ]] || { echo "Carpeta no válida: $folder"; return 1; }
    if [ -f "$log" ]; then
        tail -300 "$log"
    else
        echo "$folder aún no ha arrancado desde aquí"
    fi
}

# Tareas de la ventana (LVM_TAREA=1): lo que cambia algo pide la contraseña de administrador antes de
# empezar, no a mitad. Si se cancela, no se ha hecho nada (antes, lo hecho hasta el primer sudo se
# quedaba: el enlace de un proyecto al desmontarlo, por ejemplo). Lo que nunca la necesita, sin pedirla
if [ "${LVM_TAREA:-}" == 1 ]; then
    case "$1" in
        gui-*|node-*|exportar-bd|descargar-bd|docker-registros|construir-pila|version|--version|-v|acerca|about|novedades|procesos|limpieza|copias-ficheros|manual) ;;
        # (el tunel y los repositorios, solo con tu usuario; borrar una BBDD, solo con el MariaDB en marcha)
        tunel-abrir|tunel-instalar|tunel-cerrar|repo-traer|borrar-bd) ;;
        # (confiar: solo los almacenes de certificados de tus navegadores)
        docker-web) [ "$2" == confiar ] || { sudo_first || exit 130; } ;;
        # (importar-bd: solo si va a vaciar la cache de una tienda con ficheros de Apache)
        importar-bd) import_need_root "${@:4}" && { sudo_first || exit 130; } ;;
        # (copias: solo vaciar, y solo si hay copias de root que tu usuario no puede borrar)
        copias) [ "$2" == vaciar ] && copies_need_root && { sudo_first || exit 130; } ;;
        # (limpiar y limpiar-proyecto: solo si algo de lo que se va a limpiar es de root)
        limpiar) clean_need_root "${@:2}" && { sudo_first || exit 130; } ;;
        limpiar-proyecto) clean_project_need_root "${@:2}" && { sudo_first || exit 130; } ;;
        # (vhosts-sin-carpeta: solo quitar los cambia)
        vhosts-sin-carpeta) [ "$2" == quitar ] && { sudo_first || exit 130; } ;;
        *) sudo_first || exit 130 ;;
    esac
fi

case "$1" in
    "")
        # Abierto desde un acceso del menu de una version anterior (1.8 o antes abrian el panel en
        # GNOME Terminal, y GNOME puede seguir lanzando esa orden de su cache aunque el acceso ya
        # este al dia): si hay ventana, se abre la ventana y se cierra la terminal
        if [ "$DRY" -eq 0 ] && [ "$(ps -o sid= -p $$ 2> /dev/null | tr -d ' ')" == "$$" ] \
            && { [ -n "$DISPLAY" ] || [ -n "$WAYLAND_DISPLAY" ]; } && gui_available; then
            update_launchers
            setsid "$SELF" ventana < /dev/null > /dev/null 2>&1 &
            exit 0
        fi
        panel
        ;;
    instalar|instalador|install|panel)
        shift
        if [ $# -eq 0 ]; then
            offer_command_install
            panel_install
            [ "$UI" == "whiptail" ] && clear
        else
            cli_install "$@"
        fi
        ;;
    use) use_lampp "$2" ;;
    list) list_lampp ;;
    list-db) list_databases ;;
    status|estado) echo -e "$(status_text)" ;;
